CREATE TABLE ecommerce_channels (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,name TEXT NOT NULL,channel_type TEXT NOT NULL CHECK(channel_type IN ('web','marketplace','social')),configuration_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','rejected','retired')),created_by TEXT NOT NULL,reviewed_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE ecommerce_listings (id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES ecommerce_channels(id),product_id TEXT NOT NULL REFERENCES commerce_products(id),title TEXT NOT NULL,currency TEXT NOT NULL,price_minor BIGINT NOT NULL CHECK(price_minor>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','retired')),created_by TEXT NOT NULL,reviewed_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,UNIQUE(channel_id,product_id));
CREATE TABLE ecommerce_carts (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,branch_id TEXT NOT NULL,department_id TEXT,channel_id TEXT NOT NULL REFERENCES ecommerce_channels(id),party_id TEXT NOT NULL REFERENCES finance_parties(id),warehouse_id TEXT NOT NULL REFERENCES commerce_warehouses(id),currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','checked_out','abandoned')),created_by TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE ecommerce_cart_lines (id TEXT PRIMARY KEY,cart_id TEXT NOT NULL REFERENCES ecommerce_carts(id),listing_id TEXT NOT NULL REFERENCES ecommerce_listings(id),listing_version BIGINT NOT NULL,product_id TEXT NOT NULL,quantity_milli BIGINT NOT NULL CHECK(quantity_milli>0),price_minor BIGINT NOT NULL,ordinal BIGINT NOT NULL,UNIQUE(cart_id,listing_id));
CREATE TABLE ecommerce_checkouts (id TEXT PRIMARY KEY,cart_id TEXT NOT NULL UNIQUE REFERENCES ecommerce_carts(id),cart_version BIGINT NOT NULL,sales_order_id TEXT NOT NULL UNIQUE REFERENCES commerce_orders(id),sales_order_version BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','confirmed','partially_fulfilled','fulfilled','cancelled')),created_by TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE ecommerce_fulfillment_links (id TEXT PRIMARY KEY,checkout_id TEXT NOT NULL REFERENCES ecommerce_checkouts(id),fulfillment_id TEXT NOT NULL UNIQUE REFERENCES commerce_fulfillments(id),source_order_version BIGINT NOT NULL,status TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE ecommerce_return_links (id TEXT PRIMARY KEY,checkout_id TEXT NOT NULL REFERENCES ecommerce_checkouts(id),fulfillment_id TEXT NOT NULL,commerce_return_id TEXT NOT NULL UNIQUE REFERENCES commerce_returns(id),source_fulfillment_version BIGINT NOT NULL,status TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE FUNCTION ecommerce_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME IN ('ecommerce_fulfillment_links','ecommerce_return_links') OR TG_OP='DELETE' THEN RAISE EXCEPTION 'ECOMMERCE_HISTORY_IMMUTABLE' USING ERRCODE='23514'; END IF; IF TG_TABLE_NAME='ecommerce_listings' THEN IF (NEW.id,NEW.channel_id,NEW.product_id,NEW.currency,NEW.price_minor,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.channel_id,OLD.product_id,OLD.currency,OLD.price_minor,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'ECOMMERCE_LISTING_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='ecommerce_carts' THEN IF (NEW.id,NEW.company_id,NEW.branch_id,NEW.department_id,NEW.channel_id,NEW.party_id,NEW.warehouse_id,NEW.currency,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.branch_id,OLD.department_id,OLD.channel_id,OLD.party_id,OLD.warehouse_id,OLD.currency,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'ECOMMERCE_CART_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['ecommerce_channels','ecommerce_listings','ecommerce_carts','ecommerce_checkouts','ecommerce_fulfillment_links','ecommerce_return_links'] LOOP EXECUTE format('CREATE TRIGGER ecommerce_guard BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION ecommerce_guard()',t);END LOOP;END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['ecommerce_channels','ecommerce_listings','ecommerce_carts','ecommerce_checkouts'] LOOP INSERT INTO work_cache_revisions(table_name) VALUES(t) ON CONFLICT DO NOTHING;EXECUTE format('CREATE TRIGGER work_cache_change AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION work_cache_changed()',t);EXECUTE format('CREATE TRIGGER work_cache_truncate AFTER TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION work_cache_changed()',t);END LOOP;END $$;
